 "yungacruz-chulumani":{"t":"cerca de 1 h","how":"Desde el final del trekking, transporte a Chulumani."},
 "santacruz-camiri":{"t":"unas 5 h","how":"Bus desde la Terminal Bimodal de Santa Cruz."},
 "camiri-villamontes":{"t":"unas 3 h","how":"Bus hacia Villamontes y Yacuiba."},
 "santacruz-cotoca":{"t":"30 min","how":"Micro o taxi desde Santa Cruz."},
