 festivals: {
 "alasitas":{"name":"Alasitas","text":"La feria de las miniaturas: se compra en pequeño lo que se desea en grande (casa, auto, billetes, título) y se hace bendecir para el Ekeko, el dios de la abundancia."},
 "oruro-carnival":{"name":"Carnaval de Oruro","text":"El carnaval más grande de los Andes: decenas de miles de bailarines enmascarados, diabladas y morenadas, desfilan casi veinte horas hasta el santuario del Socavón."},
 "santacruz-carnival":{"name":"Carnaval cruceño","text":"El carnaval tropical: comparsas disfrazadas, corso, música día y noche, y guerra de agua y pintura en toda la ciudad."},
 "pujllay":{"name":"Pujllay de Tarabuco","text":"Las comunidades yampara bajan a Tarabuco con su ropa de fiesta y sus espuelas marcando el ritmo de la danza, para celebrar la cosecha y la victoria de 1816."},
 "holy-week":{"name":"Semana Santa en Copacabana","text":"Miles de peregrinos caminan toda la noche desde La Paz, unos 150 km, para llegar al santuario de la Virgen de Copacabana el Viernes Santo."},
 "chiquitos-festival":{"name":"Festival de música barroca de las misiones","text":"Durante diez días, más de cien conciertos de música barroca y renacentista en los templos misionales y en Santa Cruz, muchas veces gratuitos."},
 "granpoder":{"name":"Gran Poder","text":"La gran entrada folklórica de La Paz: miles de bailarines de morenada, caporales y diablada cruzan la ciudad con trajes bordados en oro."},
 "andean-new-year":{"name":"Año Nuevo Andino Amazónico","text":"En el solsticio de invierno se espera la salida del sol en Tiwanaku para recibir sus primeros rayos con las manos en alto. Feriado en todo el país."},
 "ichapekene":{"name":"Ichapekene Piesta","text":"La gran fiesta de San Ignacio de Moxos: los macheteros bailan con sus enormes tocados de plumas, entre tradiciones mojeñas y herencia misional."},
 "copacabana-virgin":{"name":"Virgen de Copacabana","text":"La patrona de Bolivia se celebra con procesiones, danzas y la bendición de autos frente a la basílica. Otra gran fiesta el 2 de febrero, la Candelaria."},
 "urkupina":{"name":"Virgen de Urkupiña","text":"Cientos de miles de peregrinos y bailarines en Quillacollo. El último día se sube al calvario a romper piedras, símbolo de prosperidad."},
 "chaguaya":{"name":"Peregrinación a Chaguaya","text":"Hasta mediados de septiembre, miles de peregrinos caminan desde Tarija, e incluso desde el norte argentino, hasta el santuario de la Virgen de Chaguaya."},
 "sanroque":{"name":"Fiesta Grande de Tarija (San Roque)","text":"Semanas de fiesta para San Roque, con los chunchos en trajes de plumas y cintas, las cañas y las procesiones de septiembre."},
 "chutillos":{"name":"Ch'utillos","text":"A fines de agosto, Potosí celebra a San Bartolomé y San Ignacio de Loyola con una gran entrada de danzas de todo el país, entre tradiciones andinas y coloniales."},
 "guadalupe":{"name":"Virgen de Guadalupe","text":"La patrona de Sucre, celebrada a principios de septiembre con una gran entrada folklórica por las calles del centro histórico."},
 "todos-santos":{"name":"Todos Santos","text":"En todo el país se recibe a las almas de los difuntos con mesas llenas de panes con forma de escaleras y personas (t'antawawas), y luego se las despide en el cementerio."},
 "natitas":{"name":"Fiesta de las Ñatitas","text":"En el Cementerio General de La Paz se honra a cráneos adornados con flores y lentes de sol, agradeciéndoles su protección. Una tradición sorprendente, a respetar."},
 "charango":{"name":"Festival del charango de Aiquile","text":"A principios de noviembre, músicos y luthiers de toda Bolivia se encuentran en la capital del charango para concursos y conciertos."},
 "cotoca":{"name":"Virgen de Cotoca","text":"La noche del 7 al 8 de diciembre, miles de peregrinos caminan desde Santa Cruz hasta el santuario de la patrona de los cruceños, con misa, música y feria."}
},
